import hashlib
import shutil
from collections import defaultdict
from dataclasses import dataclass, field
from pathlib import Path

@dataclass
class DuplicateReport:
    groups: list = field(default_factory=list)
    wasted_bytes: int = 0
    files_scanned: int = 0

def _sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open('rb') as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b''):
            digest.update(chunk)
    return digest.hexdigest()

def find_duplicate_files(directory: str, min_size_bytes: int=1) -> DuplicateReport:
    root = Path(directory).expanduser()
    by_size = defaultdict(list)
    report = DuplicateReport()
    for item in root.rglob('*'):
        if item.is_file() and (not item.is_symlink()):
            size = item.stat().st_size
            report.files_scanned += 1
            if size >= min_size_bytes:
                by_size[size].append(item)
    for size, paths in by_size.items():
        if len(paths) < 2:
            continue
        by_hash = defaultdict(list)
        for p in paths:
            by_hash[_sha256(p)].append(str(p))
        for digest, same in by_hash.items():
            if len(same) > 1:
                report.groups.append({'hash': digest, 'size': size, 'files': sorted(same)})
                report.wasted_bytes += size * (len(same) - 1)
                # Move extra copies into a quarantine folder, keeping the first one in place
                quarantine = root / '.duplicates_quarantine'
                quarantine.mkdir(exist_ok=True)
                for dup in sorted(same)[1:]:
                    target = quarantine / f"{digest[:12]}_{Path(dup).name}"
                    shutil.move(dup, str(target))
    return report
